import{_ as n,P as o,d as i,e as r,x as t,q as s}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"Part 8 Human State Prototypes","description":"","frontmatter":{"title":"Part 8 Human State Prototypes","xkChars":0,"xkWords":6523,"xkLessons":{"8.5.2":{"title":"Orderly exit requires more than declaring closure","lead":"Trace functions, people, resources, memory, obligations, and weak connections through the handoff.","explanation":["X0 is an independent lifecycle path, not an eighth stage or a prize available only after S5 or S6. Its completion concerns what happens to the original object and its necessary functions, people and relationships, resources, records, debts, responsibility, and weak connections.","A closure announcement, a receiving organization, or an online archive can establish a narrower fact. Completion needs actual uptake and the specified protection and review arrangements. Unknown affected groups, remaining duties, receiving capacity, appeals, or memory safety prevent the stronger claim of benign completion.","This does not make every unknown a proven failure. Record candidate, in-progress, partial, completed, or unknown status as appropriate. Records custody also differs from responsibility for unresolved obligations. Restricted access may protect vulnerable material rather than demonstrate a failed handoff."],"distinctions":[{"leftTitle":"One documented handoff","leftText":"Evidence for a specified function, resource, or record transfer.","rightTitle":"Completed X0","rightText":"Evidence covering all applicable completion conditions and unresolved obligations."}],"teachingExamples":[{"title":"Records accepted, duties unresolved","text":"Assume an archive receives an institution’s records, while no material identifies responsibility for outstanding claims. The records transfer can be supported; overall orderly-exit completion remains unknown.","assumptions":"Hypothetical example of a partial handoff.","boundary":"Unknown overall completion does not mean the archive transfer failed."}],"boundaries":["X0 classification does not grant permission to dissolve, disclose records, or abandon duties.","Access restrictions alone do not establish harmful opacity."],"questionAnswers":[{"question":"Must an organization reach a high state prototype before considering X0?","answer":"No. The exit path has its own entry and completion conditions; it is not S7 or a reward for maturity.","basis":"Theory v2, §8.5.2, with the distinctions explained above."}],"caseLinks":[{"title":"Atlantic’s archives and the limits of custody evidence","href":"/en/cases/atlantic-archives-exit"}],"sourceRefs":[{"section":"8.5.2","startLine":1931,"endLine":1946}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-08#section-8-5-2","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§8.5.2; English reading edition, lines 1931–1946","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-08.md","filePath":"en/theory/part-08.md"}'),d={name:"en/theory/part-08.md"};function c(l,e,p,h,u,m){const a=o("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=t("",1)),s(a,{section:"8.5.2"}),e[1]||(e[1]=t("",3))])}const g=n(d,[["render",c]]);export{b as __pageData,g as default};
